/**
 * @ohos/dsh-context-ledger — the data half of HarmonyGo's context panel.
 *
 * dsh already knows everything the panel needs: `token-meter` folds a
 * `contextBreakdown` (system / tools / messages) and a `contextPressure`
 * (used / window) projection, every assistant settlement carries the
 * provider's `usage` (input, output, cache read, cache write), and the
 * session log records why the window changed (injections, model switches,
 * compactions) and how long each step took. What it does not have is a
 * channel the native client can read: ACP exposes only `usage_update`
 * (used/size) and drops the rest.
 *
 * So this plugin writes compact JSONL lines into
 * `<dsh-home>/context-ledger.jsonl`. The ArkTS side parses them; nothing here
 * is model-facing (no tool schema, no prompt section) and no content is
 * logged — only counts, the provider/model identity, and the *producer kind*
 * of an injection (a plugin id, never its text).
 *
 * Three line kinds share one file so the panel can read them in commit order:
 *
 *   - settlement (`v:1`, no `k`) — one per `assistant/message`: composition,
 *     pressure, provider usage, plus the message-split and compaction budget
 *     when they are known;
 *   - event (`v:2`, `k:"e"`) — an injection, a model switch, a compaction or
 *     a tool-result prune, with its token delta;
 *   - step (`v:2`, `k:"s"`) — one per `step/end`: wall time, tool time, and
 *     how many tools the step called.
 *
 * Design constraints, all learned from the platform:
 *   - The listener runs inside the turn's event dispatch. It must never throw
 *     and never await: a slow write would delay the next step.
 *   - Writes are serialized through a promise chain with a hard pending cap;
 *     if the disk stalls, dropping ledger lines is better than blocking turns.
 *   - The file rotates at 4 MiB (one previous generation as `.1`) so a long
 *     session cannot grow it without bound.
 *   - Subagent sessions are skipped: their context is not the conversation the
 *     panel shows, and they would multiply the file.
 */
import { appendFile, mkdir, rename, stat } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join } from "node:path";

export const name = "context-ledger";
export const inject = ["sessionProjections"];

/** One previous generation is kept; more would cost more than it answers. */
const MAX_BYTES = 4 * 1024 * 1024;
/** Rotate check cadence, in appended lines. */
const ROTATE_EVERY = 64;
/** Beyond this many queued writes the ledger drops lines instead of growing. */
const MAX_PENDING = 64;

/**
 * Auto-compaction defaults from `dsh-compaction-basic`: compact at 80% of the
 * window, keeping 64k of headroom below the message budget. The `ohos` profile
 * never overrides them, so the panel can state the threshold it will hit
 * instead of guessing "70% is probably time to compact".
 */
const DEFAULT_THRESHOLD_RATIO = 0.8;
const DEFAULT_HEADROOM_TOKENS = 65536;

/** Fixed text density used by dsh's own estimator, for injection deltas. */
const CHARS_PER_TOKEN = 4;
/** Per-block structural overhead the estimator adds. */
const BLOCK_OVERHEAD = 4;
/** Role-field framing overhead the estimator adds to every message. */
const ROLE_OVERHEAD = 4;

/** Finite non-negative number, or 0. */
export function num(value) {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : 0;
}

/** The ledger path for this process; tests pass an explicit home. */
export function ledgerPath(home = process.env.DSH_HOME || join(homedir(), ".dsh")) {
  return join(home, "context-ledger.jsonl");
}

/**
 * Auto-compaction threshold for one routed window, or 0 when it cannot be
 * known. Mirrors `resolveCompactSpec`: the smaller of the ratio budget and
 * what is left of the window after the reserved completion and the headroom.
 *
 * @param window - routed context window in tokens.
 * @param reserved - tokens the request reserves for its own output.
 * @returns threshold in tokens, or 0 when the window is unknown.
 */
export function thresholdOf(window, reserved) {
  const size = num(window);
  if (size <= 0) {
    return 0;
  }
  const byRatio = Math.floor(size * DEFAULT_THRESHOLD_RATIO);
  const byBudget = size - num(reserved) - DEFAULT_HEADROOM_TOKENS;
  const threshold = Math.min(byRatio, byBudget);
  return threshold > 0 ? threshold : 0;
}

/**
 * Approximate price of one message, using dsh's fixed-density estimator.
 *
 * Only used for the token delta of an injection line. The composition split
 * reads exact per-node prices from `tokenMeter.measure()` instead, so this
 * never has to agree with the panel's totals — it just has to be close enough
 * to say "this injection was worth ≈1.2k".
 *
 * @param message - a dsh message with content blocks.
 * @returns estimated tokens, or 0 when the message carries no priceable text.
 */
export function approximateMessageTokens(message) {
  const blocks = message?.content;
  if (!Array.isArray(blocks)) {
    return typeof blocks === "string" ? Math.ceil(blocks.length / CHARS_PER_TOKEN) : 0;
  }
  let tokens = ROLE_OVERHEAD;
  for (const block of blocks) {
    if (block?.type === "text" || block?.type === "reasoning") {
      tokens += Math.ceil(String(block.text ?? "").length / CHARS_PER_TOKEN) + BLOCK_OVERHEAD;
    } else if (block?.type === "tool-call") {
      tokens += Math.ceil(String(block.name ?? "").length / CHARS_PER_TOKEN)
        + Math.ceil(String(block.arguments ?? "").length / CHARS_PER_TOKEN)
        + BLOCK_OVERHEAD;
    } else {
      tokens += BLOCK_OVERHEAD + Math.ceil(JSON.stringify(block ?? null).length / CHARS_PER_TOKEN);
    }
  }
  return tokens;
}

/**
 * The message-split bucket one surface node belongs to, or null when the node
 * is not a message the split reports (system prompts and tool schemas are
 * already their own buckets in `contextBreakdown`).
 *
 * @param event - the surface event behind one priced node.
 * @returns `"u"` human message, `"au"` assistant reply, `"tr"` tool result,
 *   `"ij"` injected context, or null for anything else.
 */
export function bucketOfEvent(event) {
  switch (event?.type) {
    case "tool/result":
      return "tr";
    case "assistant/message":
      return "au";
    case "user/message": {
      // `SessionEventMap['user/message']` is the message itself: its producer
      // lives at `data.source`, not under a `data.message` envelope.
      const kind = event?.data?.source?.kind;
      return kind === "user" ? "u" : "ij";
    }
    default:
      return null;
  }
}

/**
 * Classify one session event for the panel's "what happened" list.
 *
 * @param event - a committed session event.
 * @returns the event line's kind, label, and signed token delta, or null when
 *   the event is not worth a line.
 */
export function noticeOf(event) {
  switch (event?.type) {
    case "user/message": {
      const source = event?.data?.source ?? {};
      if (typeof source.kind !== "string" || source.kind === "user") {
        return null;
      }
      return {
        kind: "inject",
        label: source.kind,
        delta: approximateMessageTokens(event.data)
      };
    }
    case "model/selection": {
      const model = typeof event?.data?.model === "string" ? event.data.model : "";
      return model.length === 0 ? null : { kind: "model", label: model, delta: 0 };
    }
    case "compaction/summary":
      return {
        kind: "compact",
        label: typeof event?.data?.model === "string" ? event.data.model : "",
        delta: -num(event?.data?.shadowedTokenCount)
      };
    case "compaction/prune":
      return {
        kind: "prune",
        label: "",
        delta: -num(event?.data?.shadowedTokenCount)
      };
    default:
      return null;
  }
}

/**
 * Compose one ledger settlement record from a settlement event and the
 * projection views.
 *
 * `values` is `sessionProjections.snapshot(...).values`, already validated by
 * the projection's view schema; anything missing collapses to 0 so a partial
 * snapshot still produces a usable line. `extra` carries the facts that come
 * from the meter and the request header rather than a projection.
 *
 * @param session - the Session that emitted the event (its header carries the id).
 * @param event - the committed `assistant/message` event.
 * @param values - `{ contextBreakdown?, contextPressure? }` views.
 * @param extra - `{ split?, threshold?, reserved? }` meter and header facts.
 * @returns a compact record, or null when the event has no usable identity.
 */
export function recordOf(session, event, values = {}, extra = {}) {
  const sessionId = session?.header?.id;
  if (typeof sessionId !== "string" || sessionId.length === 0) {
    return null;
  }
  const breakdown = values.contextBreakdown ?? {};
  const pressure = values.contextPressure ?? {};
  const data = event?.data ?? {};
  const message = data.message ?? {};
  const source = message.source ?? {};
  const usage = data.usage ?? {};
  const system = num(breakdown.systemTokens);
  const tools = num(breakdown.toolsTokens);
  const messages = num(breakdown.messageTokens);
  const composed = system + tools + messages;
  const context = num(pressure.pressureTokens) > 0 ? num(pressure.pressureTokens) : composed;
  const record = {
    v: 1,
    t: num(event?.time),
    s: sessionId,
    turn: num(data.turn),
    step: num(data.step),
    seq: num(event?.seq),
    p: typeof source.provider === "string" ? source.provider : "",
    m: typeof source.model === "string" ? source.model : "",
    ctx: context,
    win: num(pressure.contextWindow),
    sys: system,
    tools,
    msg: messages,
    inp: num(usage.inputTokens),
    out: num(usage.outputTokens),
    cr: num(usage.cacheReadTokens),
    cw: num(usage.cacheWriteTokens),
    rs: num(usage.reasoningTokens)
  };
  const split = extra.split;
  if (split !== null && split !== undefined) {
    record.u = num(split.u);
    record.au = num(split.au);
    record.tr = num(split.tr);
    record.ij = num(split.ij);
  }
  const threshold = num(extra.threshold);
  if (threshold > 0) {
    record.thr = threshold;
  }
  const reserved = num(extra.reserved);
  if (reserved > 0) {
    record.rsv = reserved;
  }
  return record;
}

/**
 * Serialize a record. Short keys keep the file small on a phone; the reader
 * owns the mapping and version-checks `v`.
 */
export function lineOf(record) {
  return JSON.stringify(record) + "\n";
}

/** Identity a ledger line is written for, or null for a subagent session. */
function sessionIdOf(session) {
  if (session?.header?.origin === "subagent") {
    return null;
  }
  const id = session?.header?.id;
  return typeof id === "string" && id.length > 0 ? id : null;
}

/**
 * Split the current surface's messages into the panel's four buckets, scaled
 * onto the token-meter's authoritative `messageTokens` total.
 *
 * The meter prices every surface node under the routed model (including image
 * route pricing), so the split is exact up to the scaling: the four buckets
 * always add up to the number the composition card already shows.
 *
 * @param ctx - plugin context; `tokenMeter` may be absent on an older runtime.
 * @param session - the session whose surface is priced.
 * @param messages - `contextBreakdown.messageTokens` for the same moment.
 * @returns the four bucket totals, or null when the meter cannot answer.
 */
export function splitOf(ctx, session, messages) {
  const meter = ctx?.get?.("tokenMeter");
  if (typeof meter?.measure !== "function") {
    return null;
  }
  let nodes;
  try {
    nodes = meter.measure(session)?.nodes;
  } catch {
    return null;
  }
  if (!Array.isArray(nodes) || nodes.length === 0) {
    return null;
  }
  const raw = { u: 0, au: 0, tr: 0, ij: 0 };
  for (const node of nodes) {
    const bucket = bucketOfEvent(session?.eventAt?.(node.seq));
    if (bucket !== null) {
      raw[bucket] += num(node.tokens);
    }
  }
  const total = raw.u + raw.au + raw.tr + raw.ij;
  const budget = num(messages);
  if (total <= 0 || budget <= 0) {
    return null;
  }
  const scale = budget / total;
  const split = {
    u: Math.round(raw.u * scale),
    au: Math.round(raw.au * scale),
    tr: Math.round(raw.tr * scale),
    ij: 0
  };
  // The remainder rides the injected bucket so the four add up exactly.
  split.ij = Math.max(0, budget - split.u - split.au - split.tr);
  return split;
}

/**
 * Register the ledger listener.
 *
 * The projections are read synchronously from the snapshot; the token-meter's
 * own listener normally advanced them earlier in this same dispatch, so the
 * read is a lookup rather than a re-fold. A missing projection (older dsh, a
 * partially mounted profile) degrades to a record with zero composition
 * instead of dropping the usage numbers.
 */
export function apply(ctx) {
  const file = ledgerPath();
  let chain = Promise.resolve();
  let pending = 0;
  let writes = 0;
  let dirReady = false;
  let warned = false;
  /** Open steps: `turn:step` → wall clock of `step/start`, tool time, calls. */
  const steps = new Map();
  /** Open tool calls: `callId` → wall clock of `tool/call`. */
  const calls = new Map();
  /** Latest turn/step per session; the notice events do not carry them. */
  const cursors = new WeakMap();

  const warn = (error) => {
    if (warned) {
      return;
    }
    warned = true;
    const message = `[context-ledger] write failed: ${error instanceof Error ? error.message : String(error)}`;
    if (typeof ctx.logger?.warn === "function") {
      ctx.logger.warn(message);
    } else {
      console.warn(message);
    }
  };

  const append = async (line) => {
    if (!dirReady) {
      await mkdir(dirname(file), { recursive: true });
      dirReady = true;
    }
    await appendFile(file, line, "utf8");
    writes += 1;
    if (writes % ROTATE_EVERY !== 0) {
      return;
    }
    const info = await stat(file).catch(() => null);
    if (info !== null && info.size > MAX_BYTES) {
      await rename(file, `${file}.1`).catch(() => {});
    }
  };

  const enqueue = (line) => {
    if (pending >= MAX_PENDING) {
      warn(new Error(`pending queue full (${MAX_PENDING}), dropped a line`));
      return;
    }
    pending += 1;
    chain = chain
      .then(() => append(line))
      .catch(warn)
      .finally(() => {
        pending -= 1;
      });
  };

  /** One settlement line, with the split and compaction budget when known. */
  const settle = (session, event) => {
    let values = {};
    try {
      const snapshot = ctx.sessionProjections.snapshot(session, [
        "contextBreakdown",
        "contextPressure"
      ]);
      values = snapshot?.values ?? {};
    } catch {
      /* a projection failure must not fail the turn */
    }
    const breakdown = values.contextBreakdown ?? {};
    const pressure = values.contextPressure ?? {};
    const header = readHeader(session);
    const reserved = num(header?.config?.maxTokens);
    const record = recordOf(session, event, values, {
      split: splitOf(ctx, session, breakdown.messageTokens),
      threshold: thresholdOf(pressure.contextWindow, reserved),
      reserved
    });
    if (record !== null) {
      enqueue(lineOf(record));
    }
  };

  /** One "what happened" line, if the event is worth one. */
  const note = (session, event) => {
    const found = noticeOf(event);
    if (found === null) {
      return;
    }
    const cursor = cursors.get(session) ?? { turn: 0, step: 0 };
    enqueue(lineOf({
      v: 2,
      k: "e",
      t: num(event?.time),
      s: session.header.id,
      seq: num(event?.seq),
      turn: cursor.turn,
      step: cursor.step,
      kind: found.kind,
      label: found.label,
      d: found.delta
    }));
  };

  /** One step line when a step closes; a dangling step is simply forgotten. */
  const closeStep = (session, event) => {
    const sessionId = sessionIdOf(session);
    if (sessionId === null) {
      return;
    }
    const turn = num(event?.data?.turn);
    const step = num(event?.data?.step);
    const key = `${turn}:${step}`;
    const open = steps.get(key);
    if (open === undefined) {
      return;
    }
    steps.delete(key);
    enqueue(lineOf({
      v: 2,
      k: "s",
      t: num(event?.time),
      s: sessionId,
      turn,
      step,
      ms: Math.max(0, num(event?.time) - open.time),
      tool: open.tool,
      n: open.calls
    }));
  };

  ctx.on("session/event", (session, event) => {
    if (sessionIdOf(session) === null) {
      return;
    }
    switch (event?.type) {
      case "assistant/message":
        settle(session, event);
        break;
      case "turn/start":
        cursors.set(session, { turn: num(event.data?.turn), step: 0 });
        break;
      case "step/start":
        cursors.set(session, { turn: num(event.data?.turn), step: num(event.data?.step) });
        steps.set(`${num(event.data?.turn)}:${num(event.data?.step)}`, {
          time: num(event.time),
          tool: 0,
          calls: 0
        });
        break;
      case "tool/call":
        if (typeof event.data?.callId === "string") {
          calls.set(event.data.callId, num(event.time));
          bumpStep(session, event, 1);
        }
        break;
      case "tool/result": {
        const callId = event.data?.message?.toolCallId;
        const started = calls.get(callId);
        if (started !== undefined) {
          calls.delete(callId);
          bumpStep(session, event, 0, Math.max(0, num(event.time) - started));
        }
        break;
      }
      case "step/end":
        closeStep(session, event);
        break;
      default:
        note(session, event);
    }
  });

  /** Record a tool call or its elapsed time on the current step. */
  function bumpStep(session, event, calls, toolMs = 0) {
    const key = `${num(event?.data?.turn)}:${num(event?.data?.step)}`;
    const open = steps.get(key);
    if (open === undefined) {
      return;
    }
    open.calls += calls;
    open.tool += toolMs;
  }
}

/** The session's current request header, or undefined when it has none yet. */
function readHeader(session) {
  try {
    return session?.requestHeader?.();
  } catch {
    return undefined;
  }
}
